import ast,json,re
from fractions import Fraction
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PAGE_RANGES=[(46,176,176),(47,177,182),(48,183,186),(49,187,191),(50,192,195),(51,196,198),(52,199,202),(53,203,207),(54,208,214),(55,215,220),(58,221,227),(59,228,233),(60,234,238),(61,239,242),(62,243,251),(63,252,256),(66,257,263),(67,264,269),(68,270,274),(69,275,280),(70,281,284),(71,285,292),(72,293,296),(73,297,307),(75,308,309),(76,310,316),(77,317,322),(78,323,328),(79,329,336),(80,337,339)]
PAGES={n:page for page,start,end in PAGE_RANGES for n in range(start,end+1)}
EX={}
def f(s):
 s=str(s).replace(',','.').strip()
 if ' ' in s:
  w,r=s.split(); return Fraction(w)+Fraction(r) if not w.startswith('-') else Fraction(w)-Fraction(r)
 return Fraction(s)
def ans(x):
 x=f(x) if not isinstance(x,Fraction) else x
 return str(x.numerator) if x.denominator==1 else f'{x.numerator}/{x.denominator}'
def tree(src):
 def walk(n):
  if isinstance(n,ast.Constant):return str(n.value)
  if isinstance(n,ast.UnaryOp) and isinstance(n.op,ast.USub):return ans(-value(walk(n.operand)))
  if isinstance(n,ast.BinOp):
   if isinstance(n.op,ast.Pow):
    assert isinstance(n.right,ast.Constant) and n.right.value in (2,3)
    a=walk(n.left);r={'op':'multiply','left':a,'right':a}
    return r if n.right.value==2 else {'op':'multiply','left':r,'right':a}
   return {'op':{ast.Add:'add',ast.Sub:'subtract',ast.Mult:'multiply',ast.Div:'divide'}[type(n.op)],'left':walk(n.left),'right':walk(n.right)}
  raise ValueError(ast.dump(n))
 return walk(ast.parse(src,mode='eval').body)
def value(n):
 if isinstance(n,str):return f(n)
 a,b=value(n['left']),value(n['right'])
 return {'add':lambda:a+b,'subtract':lambda:a-b,'multiply':lambda:a*b,'divide':lambda:a/b}[n['op']]()
def mathtext(n,outer=True):
 if isinstance(n,str):
  s=n.replace('.',',');return '('+s+')' if '/' in s else s
 s=mathtext(n['left'])+' '+{'add':'+','subtract':'−','multiply':'·','divide':':'}[n['op']]+' '+mathtext(n['right'])
 return '('+s+')' if outer else s
def add(number,label,kind,**kw):
 if number not in EX:EX[number]={'number':number,'sourcePage':PAGES[number],'coverage':{'sourceVerified':True},'parts':[]}
 label=str(label); ident=str(number)+'-'+label
 assert ident.isascii() and not any(x['id']==ident for x in EX[number]['parts']),ident
 display={'a':'а)','b':'б)','c':'в)','d':'г)','e':'д)','f':'е)','g':'ж)','h':'з)','i':'и)','j':'к)','N':'Н','A':'А','R':'Р','B':'Б','I':'И','T':'Т','O':'О','G':'Г','word':'Расшифровка','compare':'Сравнение'}.get(label, (label.split('-')[0]+')' if label.split('-')[0].isdigit() else label));part={'id':ident,'label':display,'kind':kind,**kw};EX[number]['parts'].append(part);return part
def st(prompt,answer,explanation,hint=None):
 d={'prompt':prompt,'explanation':explanation}
 if answer is not None:d['answer']=ans(answer) if isinstance(answer,(int,float,Fraction)) else str(answer)
 if hint:d['hint']=hint
 return d
def E(n,label,src,explanation=None):
 t=tree(src);steps=[]
 def walk(x):
  if isinstance(x,str):return value(x)
  a,b=walk(x['left']),walk(x['right']);r=value(x);symbol={'add':'+','subtract':'−','multiply':'·','divide':':'}[x['op']]
  steps.append(st(f'Вычисли {ans(a)} {symbol} {ans(b)}.',ans(r),f'{ans(a)} {symbol} {ans(b)} = {ans(r)}.'))
  return r
 r=walk(t)
 return add(n,label,'expression',expression=t,answer=ans(r),steps=steps,**({'explanation':explanation} if explanation else {}))
def N(n,label,prompt,answer,steps,explanation=None):
 return add(n,label,'numeric',prompt=prompt,answer=ans(answer),steps=steps,**({'explanation':explanation} if explanation else {}))
def W(n,label,prompt,answer,criteria,steps=None):
 return add(n,label,'written',prompt=prompt,answer=answer,criteria=criteria,steps=steps or [st('Запиши решение и объясни вывод.',None,answer)])
def C(n,label,prompt,choices,answer,steps=None):
 assert answer in choices
 return add(n,label,'choice',prompt=prompt,choices=choices,answer=answer,steps=steps or [st('Выбери верное утверждение.',answer,answer)])
